import{_ as i,C as o,o as e,c as d,a0 as a,b as n,w as r,a as s,E as h,a1 as u}from"./chunks/framework.ZP6uZ4uc.js";const E=JSON.parse('{"title":"课程概览","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":null}'),c={name:"overview.md"};function A(b,t,P,g,p,k){const l=o("Mermaid");return e(),d("div",null,[t[1]||(t[1]=a('<h1 id="课程概览" tabindex="-1">课程概览 <a class="header-anchor" href="#课程概览" aria-label="Permalink to &quot;课程概览&quot;">​</a></h1><h2 id="一、学习目标" tabindex="-1">一、学习目标 <a class="header-anchor" href="#一、学习目标" aria-label="Permalink to &quot;一、学习目标&quot;">​</a></h2><p>本学习规划的目标不是在 10 周内&quot;学完&quot;概率统计、机器学习和运筹学，而是建立一套足以进入教授课题组、读懂基础论文、复现简单实验并完成小型研究项目的<strong>最低可用能力</strong>。</p><h3 id="最终目标" tabindex="-1">最终目标 <a class="header-anchor" href="#最终目标" aria-label="Permalink to &quot;最终目标&quot;">​</a></h3><p>完成本规划后，应当能够：</p><ul><li>用 Python 完成数据清洗、可视化、基础统计分析与模拟</li><li>正确区分训练集、验证集和测试集，并搭建无明显数据泄漏的机器学习流程</li><li>使用 <code>scikit-learn</code> 训练和比较基础回归、分类模型</li><li>把现实问题翻译为 Decision Variable（决策变量）、Objective Function（目标函数）和 Constraint（约束）</li><li>使用 <code>PuLP</code> 或 <code>OR-Tools</code> 建立并求解基础 LP 和 MIP 模型</li><li>完成一个&quot;预测 + 优化&quot;的端到端项目，并能向教授解释问题、假设、方法、实验和局限</li></ul><hr><h2 id="二、学习对象假设" tabindex="-1">二、学习对象假设 <a class="header-anchor" href="#二、学习对象假设" aria-label="Permalink to &quot;二、学习对象假设&quot;">​</a></h2><p>默认学习者具备：</p><ul><li>基础微积分、线性代数和高中概率知识，但可能遗忘较多</li><li>基础编程能力，理解变量、函数、循环和基本数据结构</li><li>没有系统学习过概率统计、机器学习或运筹学</li><li>可以使用 AI 辅助查错、解释代码、生成练习数据和检查思路</li><li>每周以掌握&quot;可迁移的核心概念&quot;为主，而不是追求知识点覆盖率</li></ul><hr><h2 id="三、教学表达要求" tabindex="-1">三、教学表达要求 <a class="header-anchor" href="#三、教学表达要求" aria-label="Permalink to &quot;三、教学表达要求&quot;">​</a></h2><p>整个学习网站采用纯静态实现，并满足以下要求：</p><h3 id="语言风格" tabindex="-1">语言风格 <a class="header-anchor" href="#语言风格" aria-label="Permalink to &quot;语言风格&quot;">​</a></h3><ul><li>使用尽量通俗的语言解释概念，默认读者没有相关背景</li><li>专有名词保留英文，并在首次出现时附中文，例如 <code>Random Variable（随机变量）</code></li><li>每个抽象概念至少包含： <ul><li>一个生活化例子</li><li>一个数学例子</li><li>一个代码例子</li></ul></li></ul><h3 id="内容结构" tabindex="-1">内容结构 <a class="header-anchor" href="#内容结构" aria-label="Permalink to &quot;内容结构&quot;">​</a></h3><p>每个知识点包含两类内容：</p><ul><li><strong>讲解例题</strong>：完整展示思考步骤、公式、代码和答案</li><li><strong>练习题或小项目</strong>：有真实情景，答案默认折叠</li></ul><h3 id="技术要求" tabindex="-1">技术要求 <a class="header-anchor" href="#技术要求" aria-label="Permalink to &quot;技术要求&quot;">​</a></h3><ul><li>数学公式使用 <strong>KaTeX</strong> 渲染</li><li>图示服务于理解，例如概率树、分布形状、可行域、决策树、训练误差曲线和网络流图</li><li>可嵌入或链接 Jupyter Notebook，但网页正文必须独立可读</li><li>每个模块必须有可检验的 Milestone（里程碑）</li></ul><h3 id="时间安排" tabindex="-1">时间安排 <a class="header-anchor" href="#时间安排" aria-label="Permalink to &quot;时间安排&quot;">​</a></h3><ul><li>学习进度按 Week 标记，总计 10 周</li><li>单个任务在 AI 辅助下原则上可在 2 小时内完成</li><li>考虑期中、期末压力，Week 6 和 Week 10 设计为低负荷周</li></ul><hr><h2 id="四、工具范围" tabindex="-1">四、工具范围 <a class="header-anchor" href="#四、工具范围" aria-label="Permalink to &quot;四、工具范围&quot;">​</a></h2><p>本阶段只要求掌握以下工具的<strong>最低可用部分</strong>：</p><table tabindex="0"><thead><tr><th>类别</th><th>工具</th><th>用途</th></tr></thead><tbody><tr><td>编程语言</td><td>Python</td><td>数据处理、建模、求解</td></tr><tr><td>开发环境</td><td>Jupyter Notebook</td><td>交互式编程</td></tr><tr><td>数值计算</td><td>NumPy</td><td>数组操作、向量化计算</td></tr><tr><td>数据处理</td><td>Pandas</td><td>数据读取、清洗、分组</td></tr><tr><td>可视化</td><td>Matplotlib</td><td>图表绘制</td></tr><tr><td>机器学习</td><td>scikit-learn</td><td>回归、分类、交叉验证</td></tr><tr><td>运筹优化</td><td>PuLP 或 OR-Tools</td><td>LP、MIP 建模求解</td></tr><tr><td>版本控制</td><td>Git, GitHub</td><td>代码管理、项目展示</td></tr><tr><td>文档编写</td><td>Markdown</td><td>README、笔记</td></tr></tbody></table><h3 id="本阶段不要求" tabindex="-1">本阶段不要求 <a class="header-anchor" href="#本阶段不要求" aria-label="Permalink to &quot;本阶段不要求&quot;">​</a></h3><ul><li>深度学习框架（PyTorch, TensorFlow）</li><li>高级数理统计证明</li><li>高级优化理论</li><li>求解器底层算法实现</li><li>大规模分布式训练</li><li>复杂前端框架</li></ul><hr><h2 id="五、课程设计原则" tabindex="-1">五、课程设计原则 <a class="header-anchor" href="#五、课程设计原则" aria-label="Permalink to &quot;五、课程设计原则&quot;">​</a></h2><p>整个学习规划始终遵守以下原则：</p><ol><li><strong>先建立 baseline，再谈复杂模型</strong></li><li><strong>先用小数据手算，再调用求解器</strong></li><li><strong>先检查实验是否可信，再比较指标</strong></li><li><strong>先确保模型可行，再追求最优</strong></li><li><strong>每个结论都要能用图、数字或实验支持</strong></li><li><strong>预测效果与决策效果必须分别评价</strong></li><li><strong>少学几个模型没有问题，但每个模型都要真正理解其输入、输出、假设和失败方式</strong></li><li><strong>目标是让教授看到&quot;具备被指导的基础&quot;，而不是假装已经成为该领域专家</strong></li></ol><hr><h2 id="六、五个阶段的科研主线" tabindex="-1">六、五个阶段的科研主线 <a class="header-anchor" href="#六、五个阶段的科研主线" aria-label="Permalink to &quot;六、五个阶段的科研主线&quot;">​</a></h2>',34)),(e(),n(u,null,{default:r(()=>[h(l,{id:"mermaid-399",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20P1%5BPhase%201%3A%20Understanding%20Uncertainty%5D%0A%20%20%20%20%20%20%20%20W1%5BWeek%201%3A%20%E6%95%B0%E6%8D%AE%E5%B7%A5%E5%85%B7%5D%0A%20%20%20%20%20%20%20%20W2%5BWeek%202%3A%20%E6%A6%82%E7%8E%87%E6%A8%A1%E6%8B%9F%5D%0A%20%20%20%20%20%20%20%20W3%5BWeek%203%3A%20%E7%BB%9F%E8%AE%A1%E6%8E%A8%E6%96%AD%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20P2%5BPhase%202%3A%20Prediction%5D%0A%20%20%20%20%20%20%20%20W4%5BWeek%204%3A%20ML%E5%B7%A5%E4%BD%9C%E6%B5%81%5D%0A%20%20%20%20%20%20%20%20W5%5BWeek%205%3A%20%E6%A0%91%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20%20%20%20%20W6%5BWeek%206%3A%20Mini%20Project%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20P3%5BPhase%203%3A%20Decision%5D%0A%20%20%20%20%20%20%20%20W7%5BWeek%207%3A%20LP%5D%0A%20%20%20%20%20%20%20%20W8%5BWeek%208%3A%20MIP%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20P4%5BPhase%204%3A%20Robustness%5D%0A%20%20%20%20%20%20%20%20W9%5BWeek%209%3A%20%E7%BD%91%E7%BB%9C%E4%BC%98%E5%8C%96%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20P5%5BPhase%205%3A%20Research%5D%0A%20%20%20%20%20%20%20%20W10%5BWeek%2010%3A%20Capstone%5D%0A%20%20%20%20end%0A%0A%20%20%20%20P1%20--%3E%20P2%20--%3E%20P3%20--%3E%20P4%20--%3E%20P5%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<p>每个阶段回答一个核心问题：</p><table tabindex="0"><thead><tr><th>阶段</th><th>核心问题</th><th>周次</th></tr></thead><tbody><tr><td><strong>Understanding Uncertainty</strong></td><td>数据如何产生，观察值为什么波动，我们能知道多少？</td><td>Week 1-3</td></tr><tr><td><strong>Prediction</strong></td><td>如何从历史数据中提取可泛化的信息，并建立可信的预测实验？</td><td>Week 4-6</td></tr><tr><td><strong>Decision</strong></td><td>如何把预测转化为决策变量、目标函数和约束，从而创造实际价值？</td><td>Week 7-8</td></tr><tr><td><strong>Robustness</strong></td><td>当预测、参数或假设发生变化时，决策是否仍然可靠？</td><td>Week 9</td></tr><tr><td><strong>Research</strong></td><td>如何把问题、假设、方法、实验、结论与局限组织成可复现的研究工作？</td><td>Week 10</td></tr></tbody></table><hr><h2 id="七、准备好开始了吗" tabindex="-1">七、准备好开始了吗？ <a class="header-anchor" href="#七、准备好开始了吗" aria-label="Permalink to &quot;七、准备好开始了吗？&quot;">​</a></h2><p>👉 <a href="/orml/roadmap">查看学习路线图</a> | <a href="/orml/tools-setup">安装必要工具</a> | <a href="/orml/phase1-uncertainty/week1/">开始 Week 1</a></p>',5))])}const q=i(c,[["render",A]]);export{E as __pageData,q as default};
